toolArgs.file_text:
/* Chat page layout */
.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
}

/* Channel list sidebar */
.channel-list {
    width: 20%;
    min-width: 200px;
    background: #2b2d31;
    color: #b5bac1;
    padding: 1rem 0;
    overflow-y: auto;
    border-right: 1px solid #1e1f22;
}

.channel-list-header {
    padding: 0 1rem 0.75rem;
    color: #f2f3f5;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.02em;
}

.channel-item {
    padding: 0.5rem 1rem;
    cursor: pointer;
    transition: background 0.15s;
}

.channel-item:hover {
    background: #35373c;
}

.channel-item.active {
    background: #404249;
    color: #f2f3f5;
}

.channel-name {
    display: flex;
    align-items: center;
    justify-content: space-between;
    font-weight: 500;
}

.unread-badge {
    background: #f23f43;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 0.1rem 0.4rem;
    border-radius: 8px;
    min-width: 18px;
    text-align: center;
}

.channel-description {
    font-size: 0.75rem;
    color: #80848e;
    margin-top: 0.2rem;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

/* Main message area */
.chat-main {
    flex: 1;
    display: flex;
    min-width: 0;
}

.chat-main.with-thread {
    flex: 0 0 55%;
}

.message-area {
    display: flex;
    flex-direction: column;
    flex: 1;
    background: #313338;
    min-width: 0;
}

.message-area-header {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #3f4147;
    background: #313338;
}

.message-area-header h2 {
    margin: 0;
    font-size: 1rem;
    color: #f2f3f5;
}

.message-area-header p {
    margin: 0.2rem 0 0;
    font-size: 0.8rem;
    color: #b5bac1;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 1rem;
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
}

.loading-indicator {
    text-align: center;
    padding: 0.5rem;
    color: #80848e;
    font-size: 0.8rem;
}

/* Message item */
.message-item {
    position: relative;
    padding: 0.5rem 0.75rem;
    border-radius: 4px;
    transition: background 0.1s;
}

.message-item:hover {
    background: #2e3035;
}

.message-item.highlighted {
    background: #2e3035;
    border-left: 3px solid #5865f2;
    padding-left: calc(0.75rem - 3px);
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 0.5rem;
}

.author {
    font-weight: 600;
    color: #f2f3f5;
    font-size: 0.9rem;
}

.timestamp {
    font-size: 0.7rem;
    color: #80848e;
}

.message-content {
    color: #dbdee1;
    font-size: 0.9rem;
    margin-top: 0.2rem;
    line-height: 1.4;
    white-space: pre-wrap;
    word-break: break-word;
}

.reactions {
    display: flex;
    flex-wrap: wrap;
    gap: 0.3rem;
    margin-top: 0.4rem;
}

.reaction-badge {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
    background: #2b2d31;
    border: 1px solid #3f4147;
    border-radius: 4px;
    padding: 0.15rem 0.4rem;
    font-size: 0.8rem;
    cursor: pointer;
    color: #b5bac1;
    transition: border-color 0.15s;
}

.reaction-badge:hover {
    border-color: #5865f2;
}

.thread-link {
    background: none;
    border: none;
    color: #00a8fc;
    font-size: 0.8rem;
    cursor: pointer;
    padding: 0.2rem 0;
    margin-top: 0.3rem;
    font-weight: 500;
}

.thread-link:hover {
    text-decoration: underline;
}

/* Action bar (hover) */
.action-bar {
    position: absolute;
    top: -0.5rem;
    right: 0.5rem;
    display: flex;
    gap: 0.2rem;
